create or replace TABLE KFL_PRODUCTION.DBP_DATA.ART_WUP_STATUS_PER_2 cluster by (MANDANT_ID)(
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_2 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_2 -> Counter +1',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_2 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	DAT_VON DATE NOT NULL COMMENT 'Gültigkeitsbeginn des Datensatzes. Bei der Initialübernahme eines Datensatzes wird dieses Feld mit dem Wert 01.01.1900 belegt.',
	SYSTEM_ID NUMBER(38,0) NOT NULL COMMENT 'Die System ID kennzeichnet das Quellsystem der Daten (z. B. SAP PR1)',
	LOESCH_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Löschkennzeichen: Betriebsspezifischer Artikelstatus. Die möglichen Stati sind in artkz_loesch_2 hinterlegt. aus lvorm',
	DAT_BIS DATE NOT NULL COMMENT 'Gültigkeitsende des Datensatzes. Bei der Initialübernahme eines Datensatzes wird dieses Feld mit dem Wert 31.12.9999 belegt.',
	WG_VERKETT_ID NUMBER(38,0) NOT NULL COMMENT 'Kennzeichnung der Warengruppenverkettung eines Artikels Die Warengruppenverkettung gibt an, welche Artikel_2 gemeinsam auf eine_2 Palette gepackt werden. Wird referenziert durch die Tabelle l_wg_verkettung_2',
	FREMD_LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Vorschlagslagerort für Fremdbeschaffung. Lagerorte sind in der Tabelle l_lagerort_2 enthalten. Lagerort, zu dem die Ware am Bestimmungsort in einem anderen wup_2 verbracht werden soll.',
	DISPONENT_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Disponent-ID aus dem Feld dispo',
	PPS_PLAN_KALENDER_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Id für den Planungskalender - wie oft, an welchen Wochentagen). Gilt auch für den Dispositionsrhythmus.',
	DISPOSITION_RHYTHMUS_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Id für den Dispositionsrhythmus (wie oft, an welchen Wochentagen). Gilt auch für den Planungskalender',
	PLANLIEFERZEIT NUMBER(38,0) NOT NULL COMMENT 'Planlieferzeit in Tagen',
	DISPOMERKMAL VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Schlüssel, der bestimmt, ob und wie das Material disponiert wird, z.Bsp. manuelle Bestellpunktdisposition aus dismm',
	WE_BEARBEITUNGSZEIT NUMBER(38,0) NOT NULL COMMENT 'Bearbeitungszeit für Wareneingang in Tagen aus webaz',
	MIN_SICHERH_BESTAND NUMBER(18,3) NOT NULL COMMENT 'Menge, die unterste Grenze für den Sicherheitsbestand angibt. aus eislo',
	ANLIEFER_KALENDER VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Schlüssel des Anlieferungskalender Kaufland',
	KDIS NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'kdis = kein Druck in Sortimentsliste. SAP Quellfeld ZZEK_BZGSVRS Bestellbarkeit eines Artikels. kdis 0: Artikel_2 normal bestellbar, 1:  Artikel_2 wird  zugeteilt',
	BEZUGSWEG_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Kennzeichnet, ob der Artikel_2 vom Zentrallager bezogen wird (Bezugsweg = 4) oder direkt vom Lieferanten (Bezugsweg = 1)',
	TERMINIERUNGSGRUPPE_1_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' DEFAULT '-1 ' COMMENT 'LTF: Terminierungsgruppe 1',
	TERMINIERUNGSGRUPPE_2_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' DEFAULT '-1' COMMENT 'LTF: Terminierungsgruppe 2',
	TERMINIERUNGSGRUPPE_3_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' DEFAULT '-1' COMMENT 'LTF: Terminierungsgruppe 3',
	SOLLBESTAND NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Sollbestand',
	DAT_LOESCH_ID DATE COMMENT 'Feld aus MARC.MMSTD - Datum, ab dem der betriebsspezifische Artikelstatus gültig ist',
	SELBSTABHOLUNG_FG NUMBER(38,0) COMMENT 'MARC.ZLVS_KZSELBSTABH - Kennzeichen Selbstabholung',
	MIN_RESTLAUFZEIT NUMBER(38,0) COMMENT 'Mindestrestlaufzeit in Tagen',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	DAT_LIEFERSPERRE_BIS DATE COMMENT 'Datum, bis zu dem eine_2 Liefersperre für einen bestimmten Artikel_2 oder Lieferanten verhängt wurde. Nach diesem Datum ist der Artikel_2 oder Lieferant wieder für die Lieferung freigegeben.',
	REF_WUP_ID NUMBER(38,0) COMMENT 'Referenzen für Markt-Artikel_2-Kombinationen finden, die neu sind und für die es daher keine Historie gibt:Ist der Markt neu, gibt es in Spalte VRBWK einen schon existierenden Referenzmarkt.',
	RATE_REF_ABSATZ NUMBER(38,5) DEFAULT 0 COMMENT 'Multiplikationsfaktor, mit dem der Absatz der Referenz Markt-Artikel_2-Kombination multipliziert wird für die neue Kombination.Quellfeld ist VRBFK.',
	REF_ART_ID NUMBER(38,0) COMMENT 'Referenzen für Markt-Artikel_2-Kombinationen finden, die neu sind und für die es daher keine Historie gibt: Ist der Artikel_2 neu, gibt es in Spalte VRBMT einen schon existierenden Referenzartikel.',
	DAT_REF_GUELTIG_BIS DATE COMMENT 'Markiert das Gültigkeitsende (gültig_bis) der Referenz, es gibt kein analoges gültig_von: Die Markt-Artikel_2-Kombination gilt für die gesamte Historie bis zum Datum VRBDT.',
	constraint PK_ART_WUP_STATUS_PER primary key (ART_ID, MANDANT_ID, WUP_ID, NB_ID, DAT_VON)
)COMMENT='TP408 LVS - Hier ist der Artikelstatus pro Artikel_2 und Lager hinterlegt. aus SAP MARC_2 - MULTISET'
;